    uint256 indexed escrowId,
    address indexed token,
    address from,
    address to,
    uint256 value,
    string data
);

/// Event: 移転申請取消
event CancelTransfer(
    uint256 indexed escrowId,
    address indexed token,
    address from,
    address to
);

/// Event: 移転承認
