    uint256 indexed escrowId,
    address indexed token,
    string data
);

/// Event: 移転完了
event FinishTransfer(
    uint256 indexed escrowId,
    address indexed token,
    address from,
    address to,
    string data
);
```

> **[[백준] 크로아티아 알파벳](https://www.acmicpc.net/problem/2941)**

	- 각 알파벳 뒤로 오는 경우를 카운트
	
```java

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.*;

public class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        
        String[] S = new String[N];
        
        for(int i = 0; i<N; i++){
            S[i] = br.readLine(); 
        }
        
        Arrays.sort(S,new Comparator<String>() { 
            @Override public int compare(String o1, String o2) { 
                if(o1.length()==o2.length()) return o1.compareTo(o2);
                return o1.length()-o2.length();
                } 
        });


        System.out.println(S[0]);
        
        for(int i = 1; i<N; i++){
            if(S[i-1].equals(S[i])) continue;
            System.out.println(S[i]);
        }
    }
    
}


```


> **[[백준] 수 정렬하기 2](https://www.acmicpc.net/problem/2751)**

	Arrya.sort + System.out.print로는 시간 초과가 남
	* Array.sort 와 CountingSort을 사용하여 해결
	* Array.sort 시간 : 1632ms
	* Counting Sort 시간 : 884

	[추가]
	Arrya.sort() : dual-pivot Quicksort (O(n) ~ (O(n^2)
	Collections.sort() : hybrid sorting algorithm(O(n) ~ (O(nlogn)
	두가지가 섞여있는 알고리즘 Collections.sort() 는 Tim sort로
	합병 + 삽입 정렬 알고리즘
	
```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.*;

public class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        String[] alpha = {"c=", "c-", "dz=", "d-", "lj", "nj", "s=", "z="};
         
        int n = Integer.parseInt(br.readLine());
        int[] arr = new int[n];
        
        for(int i = 0; i<n; i++){
            arr[i] = Integer.parseInt(br.readLine());
        }
        
        Arrays.sort(arr);
        
        for(int i : arr){
            bw.write(String.valueOf(i));
            bw.write("\n");   
        }
        
        bw.flush();
        bw.close();
    }
    
}
```

	Counting sort 를 이용한 정렬

```java
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.*;

public class Main{
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        int n = Integer.parseInt(br.readLine());
        boolean[] arr = new boolean[2000001];
        
        for(int i = 0; i<n; i++){
            arr[Integer.parseInt(br.readLine())+1000000] = true;
        }
        
        
        for(int i = 0; i<arr.length; i++){
            if(arr[i]==true){
                bw.write(String.valueOf(i-1000000));
                bw.write("\n");
            }
               
        }
        
        bw.flush();
        bw.close();
    }
    
}

```

